using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class BasicActorOperations:RefCounted
{
    private readonly ModelSourceLink _links=new();private readonly FogEnvironmentOperations _fogEnvironment=new();private readonly FogLightingOperations _lighting=new();
    private static Resource Actor(Node3D owner)=>owner.Get("actor").As<Resource>();private static Node? Content(Node3D owner)=>owner.Get("content").As<Node>();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.GetValueOrDefault(key,fallback);
    public MeshInstance3D new_mesh_instance()=>new(){Layers=1};public StandardMaterial3D new_standard_material()=>new(){Transparency=BaseMaterial3D.TransparencyEnum.Disabled,CullMode=BaseMaterial3D.CullModeEnum.Back};
    public Light3D new_light(int kind){Light3D light=kind switch{1=>new OmniLight3D(),2=>new SpotLight3D(),_=>new DirectionalLight3D()};light.LightCullMask=1;return light;}
    public void assign_material_override(Node3D owner,Material? value){var content=Content(owner);if(content is MeshInstance3D mesh)mesh.MaterialOverride=value;else if(content!=null)foreach(var child in content.FindChildren("*","MeshInstance3D",true,false))((MeshInstance3D)child).MaterialOverride=value;}
    public void ready(Node3D owner)
    {
        owner.AddToGroup("actor_shader_runtimes");Node? content=null;switch(Actor(owner).Get("type_id").AsString()){case "powder":case "fluid":content=owner.Get("content").As<Node>()??new Node3D();break;case "basic_shape":content=new_mesh_instance();owner.Set("content",content);var standard=new_standard_material();owner.Set("material",standard);assign_material_override(owner,standard);break;case "basic_mesh":content=new Node3D();break;case "text_3d":var text=new Label3D{Layers=1};var shadow=new Label3D{Layers=1};owner.Set("text_shadow",shadow);text.AddChild(shadow);content=text;break;case "light_3d":case "directional_light":content=new_light(0);break;case "camera_3d":var camera=new Camera3D{CullMask=1};content=camera;add_camera_guide(camera);var canvas=new CanvasLayer{Layer=100};owner.Set("camera_canvas",canvas);owner.AddChild(canvas);var overlay=new ColorRect{Color=Colors.White,MouseFilter=Control.MouseFilterEnum.Ignore};owner.Set("camera_overlay",overlay);canvas.AddChild(overlay);overlay.SetAnchorsAndOffsetsPreset(Control.LayoutPreset.FullRect);overlay.Hide();break;case "image_3d":var image=new_mesh_instance();image.Mesh=new QuadMesh{Size=Vector2.One};content=image;owner.Set("content",content);var imageMaterial=new_standard_material();owner.Set("material",imageMaterial);assign_material_override(owner,imageMaterial);break;case "world_environment":owner.Set("_world_environment_resource",new Godot.Environment());content=new Node3D();break;case "decal_3d":content=new Decal();break;case "particles_3d":var particles=new GpuParticles3D();particles.Set("use_fixed_seed",true);particles.Set("seed",GD.Hash(Actor(owner).Get("id").AsString())&0x7fffffff);var particleMaterial=new ParticleProcessMaterial();owner.Set("particle_material",particleMaterial);particles.ProcessMaterial=particleMaterial;particles.DrawPass1=new SphereMesh{Radius=.08f,Height=.16f};content=particles;break;case "fog_volume":case "global_fog":var fogMaterial=new FogMaterial();owner.Set("fog_material",fogMaterial);content=new FogVolume{Material=fogMaterial};break;case "reflection_probe":content=new ReflectionProbe();break;}owner.Set("content",content!=null?Variant.From(content):default);if(content!=null)owner.AddChild(content);if(content is FogVolume)_fogEnvironment.attach(owner);var anchor=new Node3D{Name="ParentingAnchor"};owner.Set("parenting_anchor",anchor);owner.AddChild(anchor);var actor=Actor(owner);if(_links.register_actor(actor,owner)){owner.AddToGroup("model_instance_runtimes");owner.CallDeferred("refresh_model_binding",actor.Get("values").AsGodotDictionary().GetValueOrDefault("model_component_source","").AsString());}
    }
    public void add_camera_guide(Camera3D camera)
    {
        var lines=new ImmediateMesh();var paint=new StandardMaterial3D{ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded,AlbedoColor=new Color("70d7f2"),NoDepthTest=true};lines.SurfaceBegin(Mesh.PrimitiveType.Lines,paint);var back=new[]{new Vector3(-.16f,-.11f,.08f),new Vector3(.16f,-.11f,.08f),new Vector3(.16f,.11f,.08f),new Vector3(-.16f,.11f,.08f)};var front=new[]{new Vector3(-.42f,-.24f,-.65f),new Vector3(.42f,-.24f,-.65f),new Vector3(.42f,.24f,-.65f),new Vector3(-.42f,.24f,-.65f)};for(int i=0;i<4;i++){foreach(var ring in new[]{back,front}){lines.SurfaceAddVertex(ring[i]);lines.SurfaceAddVertex(ring[(i+1)%4]);}lines.SurfaceAddVertex(back[i]);lines.SurfaceAddVertex(front[i]);}lines.SurfaceAddVertex(new Vector3(0,.11f,.08f));lines.SurfaceAddVertex(new Vector3(0,.26f,.08f));lines.SurfaceEnd();camera.AddChild(new MeshInstance3D{Name="EditorCameraGuide",Layers=2,CastShadow=GeometryInstance3D.ShadowCastingSetting.Off,Mesh=lines});
    }
    public Node parenting_node(Node3D owner)=>owner.Get("parenting_anchor").As<Node3D>()??owner;
    public bool supports_remote_transform(Node3D owner)=>Content(owner) is Node3D;
    public Transform3D remote_transform(Node3D owner)=>Content(owner) is Node3D node?node.GlobalTransform:Transform3D.Identity;
    public void apply_remote_transform(Node3D owner,Transform3D source,bool position,bool rotation,bool scale){if(Content(owner) is not Node3D node)return;var result=node.GlobalTransform;if(position)result.Origin=source.Origin;var orientation=rotation?source.Basis.GetRotationQuaternion():result.Basis.GetRotationQuaternion();var dimensions=scale?source.Basis.Scale:result.Basis.Scale;result.Basis=new Basis(orientation)*Basis.FromScale(dimensions);node.GlobalTransform=result;owner.Get("parenting_anchor").As<Node3D>().GlobalTransform=result;}
    public World3D? runtime_world(Node3D owner,bool create){var viewport=owner.GetViewport();if(viewport==null)return null;if(viewport.World3D==null&&create)viewport.World3D=new World3D();return viewport.World3D;}
    public void update_camera_overlay(Node3D owner){var overlay=owner.Get("camera_overlay").As<ColorRect>();if(overlay==null)return;var material=owner.Get("camera_shader_material").As<ShaderMaterial>();overlay.Visible=owner.Get("active").AsBool()&&Content(owner) is Camera3D camera&&camera.IsCurrent()&&material?.Shader!=null;}
    public void set_active(Node3D owner,bool active){var content=Content(owner);if(content==null)return;if(content is Node3D node)node.Visible=active;var actor=owner.Get("actor").As<Resource>();if(actor!=null&&actor.Get("type_id").AsString()=="world_environment"&&!active){var world=runtime_world(owner,true);if(world!=null&&world.Environment==owner.Get("_world_environment_resource").As<Godot.Environment>())world.Environment=owner.Get("_previous_environment").As<Godot.Environment>();}if(content is Camera3D camera&&!active){camera.ClearCurrent();update_camera_overlay(owner);}if(content is GpuParticles3D particles){bool emitting=active&&owner.Get("_particle_emitting").AsBool();if(particles.Emitting!=emitting)particles.Emitting=emitting;}}
    public void evaluate_transform(Node3D owner,Settings values){if(Actor(owner).Get("type_id").AsString()=="light_3d")ensure_light(owner,Get(values,"light_type",0).AsInt32());if(Content(owner) is not Node3D spatial)return;var anchor=owner.Get("parenting_anchor").As<Node3D>();var position=Get(values,"position",Vector3.Zero).AsVector3();var rotation=Get(values,"rotation",Vector3.Zero).AsVector3();var scale=Get(values,"scale",Vector3.One).AsVector3();spatial.Position=position;spatial.RotationDegrees=rotation;spatial.Scale=scale;anchor.Position=position;anchor.RotationDegrees=rotation;anchor.Scale=scale;if(values.TryGetValue("model_basis_residual",out var residual)){var basis=Basis.FromEuler(spatial.Rotation)*Basis.FromScale(scale)*residual.AsBasis();spatial.Basis=basis;anchor.Basis=basis;}}
    public void ensure_light(Node3D owner,int kind){if(kind==owner.Get("_light_kind").AsInt32()&&Content(owner) is Light3D)return;owner.Set("_light_kind",kind);var old=Content(owner);var light=new_light(kind);owner.Set("content",light);owner.AddChild(light);if(old!=null){if(old is Node3D node)node.Hide();old.QueueFree();}}
}
